update public.changelog
   set omschrijving = 'Gewerkte uren op een echt project worden beoordeeld door de teamleider en daarna de projectleider van dat dossier — ook die van kantoor, want het is hun project. Verlof, ziekte, vakantie, tijd-voor-tijd én alles wat op een indirecte-urenproject staat gaan naar één vaste goedkeurder. Die stel je per medewerker in op zijn profiel onder Organisatie; kies je daar niets, dan gaat het naar de goedkeurder die op Instellingen, Uren staat. Op het urenoverzicht zie je in de kolom "Wacht op" per regel wie er aan zet is.'
 where datum = '2026-09-14'
   and titel = 'Wie keurt welke uren goed';
